+/** Theoretical vs actual consumption per item between two days (inclusive). */
+export function varianceReport(store, from, to) {
+  const theoByItem = new Map();
+  for (const s of store.data.sales ?? []) {
+    const day = dayOf(s.soldAt);
+    if (day < from || day > to) continue;
+    const dish = (store.data.dishes ?? []).find((d) => d.id === s.dishId);
+    if (!dish) continue;
+    const recipe = store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, s.qty)) {
+      if (n.qty <= 0) continue;
+      theoByItem.set(n.itemId, roundQty((theoByItem.get(n.itemId) ?? 0) + n.qty));
+    }
+  }
