@@ -0,0 +1,65 @@
+// Till sales: each dish sold consumes one portion of its recipe per `qty`,
+// recorded with ref `sale:<ticket>`. Tickets already imported are skipped.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { scaled } from "./recipes.js";
+
+const roundQty = (n) => Math.round(n * 1000) / 1000 || 0;
+
+/** Records validated till sale rows, skipping known tickets; all-or-nothing. */
+export function recordSales(store, rows) {
+  const knownTickets = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const prepared = rows.map((r) => {
+    const where = `row ${r.rowNum}`;
+    const dish = (store.data.dishes ?? []).find((d) => d.id === r.dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `${where}: unknown dish` });
+    const recipe = store.data.recipes.find((rec) => rec.id === dish.recipeId);
+    if (!recipe) throw new AppError("bad_request", { reason: `${where}: unknown recipe` });
+    return { ...r, needs: scaled(recipe, r.qty) };
+  });
+
+  const toImport = prepared.filter((r) => !knownTickets.has(r.ticket));
+  const remaining = new Map();
+  for (const r of toImport) {
+    const where = `row ${r.rowNum}`;
+    for (const n of r.needs) {
+      if (n.qty <= 0) continue;
+      const item = getItem(store, n.itemId);
+      const avail = remaining.has(n.itemId) ? remaining.get(n.itemId) : roundQty(onHand(store, n.itemId));
+      if (avail < n.qty) {
+        throw new AppError("not_enough_stock", {
+          item: `${item.name} (${where})`,
+          available: avail,
+          unit: item.unit,
+        });
+      }
+      remaining.set(n.itemId, roundQty(avail - n.qty));
+    }
+  }
+
+  store.data.sales ??= [];
+  const snapshot = structuredClone(store.data);
+  try {
+    for (const r of toImport) {
+      for (const n of r.needs) {
+        if (n.qty > 0) consume(store, n.itemId, n.qty, { at: r.soldAt, ref: `sale:${r.ticket}` });
+      }
+      store.data.sales.push({
+        id: store.nextId("sale"),
+        ticket: r.ticket,
+        soldAt: r.soldAt,
+        dishId: r.dishId,
+        qty: r.qty,
+      });
+    }
+  } catch (e) {
+    store.data = snapshot;
+    throw e;
+  }
+
+  return {
+    tickets: new Set(toImport.map((r) => r.ticket)).size,
+    dishes: toImport.reduce((sum, r) => sum + r.qty, 0),
+  };
+}
