+++ b/src/io/sales-import.js
@@ -0,0 +1,37 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty).
+// Checks the whole file first; one bad row or stock-out imports nothing.
+import { isInstant } from "../dates.js";
+import { recordSales } from "../domain/sales.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+function positiveInt(raw) {
+  if (!raw || /^[+-]?0x/i.test(raw)) return null;
+  const n = Number(raw);
+  return Number.isSafeInteger(n) && n >= 1 ? n : null;
+}
+
+/** Imports sales from CSV text; returns { tickets, dishes } or throws naming the row. */
+export function importSales(store, text) {
+  const [head = [], ...rawRows] = parseCsv(text);
+  const keys = head.map((h) => h.trim());
+  for (const k of HEADER) {
+    if (!keys.includes(k)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+  }
+  const clean = rawRows.map((raw, i) => {
+    const rowNum = i + 2;
+    const where = `row ${rowNum}`;
+    if (raw.length > keys.length) throw new AppError("bad_request", { reason: `${where}: too many columns` });
+    const r = Object.fromEntries(keys.map((k, idx) => [k, (raw[idx] ?? "").trim()]));
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const dishId = positiveInt(r.dishId);
+    if (dishId === null) throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    const qty = positiveInt(r.qty);
+    if (qty === null) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    return { rowNum, ticket: r.ticket, soldAt: r.soldAt, dishId, qty };
+  });
+  return recordSales(store, clean);
+}
